{"command": "python3 <<'PY'
import subprocess, os, time, pty, fcntl, termios, struct, select
def run_capture(binary, args):
    open("/tmp/ping.log","w").write("")
    env=dict(os.environ); env["PATH"]="/tmp/fakebin:"+env["PATH"]; env["TERM"]="xterm-256color"
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", 24,80,0,0))
    p=subprocess.Popen([binary]+args, stdin=slave, stdout=slave, stderr=slave, env=env)
    import os as _os; _os.close(slave)
    flags=fcntl.fcntl(master, fcntl.F_GETFL)
    fcntl.fcntl(master, fcntl.F_SETFL, flags|_os.O_NONBLOCK)
    out=b""
    start=time.time()
    while time.time()-start<3:
        r,_,_=select.select([master],[],[],0.5)
        if r:
            try:
                d=_os.read(master,8192)
                if not d: break
                out+=d
            except: break
        if p.poll() is not None:
            try:
                while True:
                    d=_os.read(master,8192)
                    if not d: break
                    out+=d
            except: pass
            break
    rc=p.poll()
    if rc is None:
        try: p.terminate()
        except: pass
        try: p.wait(timeout=1)
        except: p.kill()
        rc=p.returncode
    _os.close(master)
    return rc, out, open("/tmp/ping.log").read()

rc,out,log=run_capture("./target/debug/gping",["--watch-interval=0.15","127.0.0.1"])
print(f"RC={rc} LOG={repr(log)} OUT={repr(out[:2000].decode(errors='replace'))}")
PY"}

